CREATE TABLE users (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, phone text, email text, password_salt text, password_hash text, must_change_password boolean NOT NULL DEFAULT false, failed_attempts int NOT NULL DEFAULT 0, locked_at timestamptz, roles text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id, phone), UNIQUE(school_id, email));
